INSERT INTO public.categories (id, name, slug, parent_id, created_at, updated_at, image_path) VALUES ('d037ece8-33d7-49ce-be0d-75e1277aaa5c', 'Hair Removal', 'hair-removal', '08e572a6-170e-437b-966d-69e62382bbe9', '2026-08-17 13:00:45.876249+00', '2026-08-17 13:00:45.876249+00', NULL);
INSERT INTO public.products (id, name, slug, description, price, currency, status, category_id, created_at, updated_at) VALUES ('7c4e8a2e-66ae-4f60-93ca-5d9f98211011', 'Sunscreen', 'sunscreen', 'Protect your skin every single day with this broad-spectrum SPF 50 PA++++ sunscreen, engineered to defend against UVA, UVB, and blue light exposure from screens. Unlike traditional sunscreens that leave a heavy, greasy, or white-cast finish, this lightweight lotion absorbs within seconds and sits invisibly under makeup or alone. It is enriched with antioxidants that help combat premature signs of ageing caused by sun damage, including fine lines, dark spots, and loss of elasticity. Water-resistant and non-comedogenic, it is safe for daily use even on acne-prone and sensitive skin without clogging pores. Make it the final step of your morning skincare routine, reapplying every three to four hours when outdoors for complete protection.', 399.00, 'INR', 'active', 'bb39a679-6154-4e4a-833d-abe773ff245d', '2026-08-18 10:59:29.934624+00', '2026-08-18 11:03:09.718522+00');
INSERT INTO public.products (id, name, slug, description, price, currency, status, category_id, created_at, updated_at) VALUES ('93bc18c5-7399-4e5d-aef8-56e0a4d6ea5f', 'Niacinamide Serum', 'niacinamide-serum', 'Refine your skin''s texture and control excess oil with this 10% Niacinamide and Zinc serum, a powerhouse combination trusted for balancing oily and combination skin. Niacinamide works to visibly minimize the appearance of enlarged pores, regulate sebum production, and strengthen your skin''s natural moisture barrier, while zinc adds an extra layer of oil control and soothing benefit for blemish-prone areas. This lightweight, fast-absorbing serum layers easily under moisturizer and makeup without any stickiness or pilling. With daily use, skin looks noticeably smoother, less shiny by midday, and more resilient against breakouts and irritation. A versatile everyday serum suitable for oily, acne-prone, and combination skin types.', 549.00, 'INR', 'active', '5e0014ae-4b5d-4a53-bfc1-2bbf4ea72862', '2026-08-18 10:59:29.934624+00', '2026-08-18 11:03:09.796955+00');
INSERT INTO public.products (id, name, slug, description, price, currency, status, category_id, created_at, updated_at) VALUES ('c3a6e87c-8ce3-4c54-8590-45e7b3014143', 'Hair Removal Powder', 'hair-removal-powder', 'Experience a gentler way to remove unwanted body hair with this herbal hair removal powder, formulated to work with your skin rather than against it. Made with a blend of soothing botanical extracts, it works to painlessly loosen hair from the root without the harsh chemical smell, burning sensation, or skin irritation associated with conventional hair removal creams. Simply mix with water to form a smooth paste, apply to the desired area, and rinse off to reveal soft, smooth, hair-free skin. The nourishing formula also helps calm and hydrate skin post-application, minimizing redness and razor-bump-like irritation. A natural, at-home alternative to waxing and shaving suitable for all skin types, including sensitive skin.', 349.00, 'INR', 'active', 'd037ece8-33d7-49ce-be0d-75e1277aaa5c', '2026-08-18 10:59:29.934624+00', '2026-08-18 11:03:09.87519+00');
INSERT INTO public.products (id, name, slug, description, price, currency, status, category_id, created_at, updated_at) VALUES ('856a40b9-e8ec-41d2-9403-f18e5fc6a2e8', 'Hair Oil', 'hair-oil', 'Strengthen your hair from root to tip with this nourishing blend of cold-pressed onion oil, argan oil, and rosemary extract, three ingredients long trusted for supporting healthy hair growth. Onion oil is rich in sulphur, which helps improve blood circulation to the scalp and reduce hair fall, while rosemary extract stimulates hair follicles to encourage thicker, fuller-looking hair over time. Argan oil deeply conditions each strand, taming frizz and adding a natural, healthy shine without weighing hair down. Unlike heavy traditional hair oils, this lightweight, fast-absorbing formula won''t leave a greasy residue, making it comfortable for regular scalp massages or an overnight treatment. Massage into the scalp two to three times a week, leave in for at least an hour or overnight, and wash out with a gentle shampoo for visibly stronger, shinier hair within weeks.', 499.00, 'INR', 'active', '08e572a6-170e-437b-966d-69e62382bbe9', '2026-08-18 12:18:43.254532+00', '2026-08-18 12:24:01.106052+00');
INSERT INTO public.products (id, name, slug, description, price, currency, status, category_id, created_at, updated_at) VALUES ('8c1fe491-945f-431a-9df0-26945769c088', 'Vitamin C Serum', 'vitamin-c-serum', 'Unlock brighter, more radiant skin with this potent 10% Vitamin C serum, one of the most researched and trusted ingredients in skincare for tackling dullness and uneven tone. This lightweight, fast-absorbing serum works to visibly fade dark spots, sun damage, and post-acne marks while boosting collagen production for firmer, more youthful-looking skin over time. Formulated with stable, skin-friendly Vitamin C derivatives, it delivers powerful antioxidant protection against daily environmental stressors like pollution and UV exposure without the irritation associated with harsher forms of the ingredient. A few drops each morning, followed by sunscreen, is all it takes to reveal a visibly more even, luminous complexion within weeks. Suitable for all skin types, including sensitive skin when introduced gradually.', 599.00, 'INR', 'active', '5e0014ae-4b5d-4a53-bfc1-2bbf4ea72862', '2026-08-18 12:41:52.491413+00', '2026-08-18 12:41:52.491413+00');
